//! 🧭️ A paid registry visit retains its exact returned original in a caller-owned frame.
use super::{ReadAuthority,Slot,READ_LEASE_CAPACITY};
use crate::{RetainedAllocationEffect,RetirementDemand,ValueError,ValueRefusalKind,retained_clone::{OriginalEffectReply,OriginalEffectReplyComplete,OriginalWorkBindingIdentity,RetainedCloneProgress,RetainedCloneStep,retained_clone_grant_admits},retirement::{RetireOwned,arc_custody::original::SharedOriginalStorage}};
use semio_framework_value_retirement::OriginalRetirementFailure;
use std::{mem::{size_of,ManuallyDrop},sync::atomic::Ordering};
type Reply<'r>=OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>;
type Complete<'r>=OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>;
fn invalid(message:&'static str)->ValueError{ValueError::invariant(message)}
fn header(copy_bytes:usize)->RetirementDemand{RetirementDemand{copy_bytes,depth:1,..Default::default()}}

/// 📬️ One visit owns its returned original until the actual caller pays its transfer.
pub struct ReadVisit<T:RetireOwned+Sync>{root:ManuallyDrop<Option<SharedOriginalStorage<T>>>,work:Option<OriginalWorkBindingIdentity>}
impl<T:RetireOwned+Sync> ReadVisit<T>{
 /// 👁️ Borrows the real returned original without moving its owner.
 pub fn root(&self)->Option<&T>{self.root.as_ref().map(SharedOriginalStorage::get)}
 /// 📏️ Quotes the exact returned-alias transfer.
 pub fn take_demand(&self)->Result<RetirementDemand,ValueError>{if self.root.is_none(){return Err(invalid("read visit has no returned original"))}Ok(header(2*size_of::<Option<SharedOriginalStorage<T>>>()))}
 /// 📤️ Transfers the original alias into an empty caller-owned slot.
 pub fn take_into<'r>(&mut self,output:&mut Option<SharedOriginalStorage<T>>,effect:&mut RetainedAllocationEffect<'_>,reply:Reply<'r>)->Result<Complete<'r>,ValueError>{if !self.work.is_some_and(|work|work.matches_effect(effect)){return Err(invalid("read visit changed original Work"))}if output.is_some(){return Err(invalid("read visit output occupied"))}let d=self.take_demand()?;if effect.remaining_work_units()?<1||!retained_clone_grant_admits(effect.grant(),d){return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}match effect.performed(1){Ok(true)=>{},Ok(false)=>return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"read visit transfer exceeded original Work").into()))),Err(error)=>return Ok(reply.complete(Err(error.into())))}*output=self.root.take();Ok(reply.complete(Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))))}
 /// 📏️ Quotes the settled visit header and its Work-binding clear.
 pub fn finish_demand()->RetirementDemand{header(size_of::<Option<Self>>()+size_of::<Option<OriginalWorkBindingIdentity>>())}
 /// 🏁️ Clears only a visit whose returned original is already transferred.
 pub fn finish_into<'r>(visit:&mut Option<Self>,effect:&mut RetainedAllocationEffect<'_>,reply:Reply<'r>)->Result<Complete<'r>,ValueError>{let owner=visit.as_mut().ok_or_else(||invalid("read visit absent"))?;if !owner.work.is_some_and(|work|work.matches_effect(effect)){return Err(invalid("read visit changed original Work"))}if owner.root.is_some(){return Err(invalid("read visit retains its returned original"))}let d=Self::finish_demand();if effect.remaining_work_units()?<1||!retained_clone_grant_admits(effect.grant(),d){return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}match effect.performed(1){Ok(true)=>{},Ok(false)=>return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"read visit finish exceeded original Work").into()))),Err(error)=>return Ok(reply.complete(Err(error.into())))}owner.work=None;drop(visit.take());Ok(reply.complete(Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))))}
}
impl<T:RetireOwned+Sync> Drop for ReadVisit<T>{fn drop(&mut self){if std::thread::panicking(){return}assert!(self.root.is_none()&&self.work.is_none(),"read visit retains its original owner");unsafe{ManuallyDrop::drop(&mut self.root)}}}

impl<T:RetireOwned+Sync> ReadAuthority<T>{
 /// 🧭️ Positions the next registry visit under the original funded action.
 pub fn seek_visit_into<'r>(&self,cursor:usize,effect:&mut RetainedAllocationEffect<'_>,reply:Reply<'r>)->Result<Complete<'r>,ValueError>{self.authenticate(effect)?;if cursor>=READ_LEASE_CAPACITY{return Err(invalid("read visit cursor is out of range"))}let registry=self.registry()?;let demand=header(size_of::<usize>());if effect.remaining_work_units()?<2||!retained_clone_grant_admits(effect.grant(),demand){return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}match effect.performed(1){Ok(true)=>{},Ok(false)=>return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"read visit seek lock exceeded Work").into()))),Err(error)=>return Ok(reply.complete(Err(error.into())))}let mut state=match registry.state.try_lock(){Ok(state)=>state,Err(error)=>return Ok(reply.complete(Err(error.into())))};match effect.performed(1){Ok(true)=>{},Ok(false)=>return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"read visit seek exceeded Work").into()))),Err(error)=>return Ok(reply.complete(Err(error.into())))}state.cursor=cursor;Ok(reply.complete(Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()}))))}
 /// 📏️ Bounds one FIFO visit, including the largest actual returned-owner transfer.
 pub fn visit_demand()->RetirementDemand{header(size_of::<Option<ReadVisit<T>>>()+3*size_of::<usize>()+size_of::<u64>()+size_of::<u16>()+size_of::<Option<Slot<T>>>())}
 /// ⛽️ Bounds the lock, every possible occupied-word inspection and selected metadata writes.
 pub fn visit_work_demand()->u64{1+(READ_LEASE_CAPACITY/64+1)as u64+7}
 /// 📨️ Publishes the exact next visit while the same issued registry remains resident.
 pub fn visit_into<'r>(&self,output:&mut Option<ReadVisit<T>>,effect:&mut RetainedAllocationEffect<'_>,reply:Reply<'r>)->Result<Complete<'r>,ValueError>{self.authenticate(effect)?;if output.is_some(){return Err(invalid("read visit output occupied"))}let d=Self::visit_demand();let work=Self::visit_work_demand();if effect.remaining_work_units()?<work||!retained_clone_grant_admits(effect.grant(),d){return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}let registry=self.registry()?;match effect.performed(1){Ok(true)=>{},Ok(false)=>return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"read visit lock exceeded original Work").into()))),Err(error)=>return Ok(reply.complete(Err(error.into())))}let mut state=match registry.state.try_lock(){Ok(state)=>state,Err(error)=>return Ok(reply.complete(Err(error.into())))};let mut selected=None;for offset in 0..=state.occupied.len(){match effect.performed(1){Ok(true)=>{},Ok(false)=>return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"read visit scan exceeded original Work").into()))),Err(error)=>return Ok(reply.complete(Err(error.into())))}let word=(state.cursor/64+offset)%state.occupied.len();let mut occupied=state.occupied[word];if offset==0{occupied&=u64::MAX<<(state.cursor%64)}else if offset==state.occupied.len(){occupied&=(1u64<<(state.cursor%64))-1}if occupied!=0{selected=Some(word*64+occupied.trailing_zeros()as usize);break}}let returned=match selected{Some(index)=>match state.slots.as_ref().and_then(|slots|slots[index].as_ref()){Some(slot)=>slot.returned,None=>return Ok(reply.complete(Err(invalid("read occupied slot absent").into())))},None=>false};if returned&&(state.free.is_none()||state.free_len>=READ_LEASE_CAPACITY){return Ok(reply.complete(Err(invalid("read free queue is invalid").into())))}let units=if returned{7}else if selected.is_some(){2}else{1};match effect.performed(units){Ok(true)=>{},Ok(false)=>return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"read visit publication exceeded original Work").into()))),Err(error)=>return Ok(reply.complete(Err(error.into())))}let root=if let Some(index)=selected{state.cursor=(index+1)%READ_LEASE_CAPACITY;if returned{let slot=state.take(index);registry.returned.fetch_sub(1,Ordering::AcqRel);Some(slot.owner)}else{None}}else{None};let copied=size_of::<Option<ReadVisit<T>>>()+usize::from(selected.is_some())*size_of::<usize>()+usize::from(returned)*(size_of::<Option<Slot<T>>>()+size_of::<u64>()+size_of::<u16>()+2*size_of::<usize>());*output=Some(ReadVisit{root:ManuallyDrop::new(root),work:Some(OriginalWorkBindingIdentity::from_effect(effect))});Ok(reply.complete(Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:copied,..Default::default()}))))}
}

impl<T:RetireOwned+Sync> ReadAuthority<T>{
 /// 📏️ Quotes the real sequence, generation and four revision writes.
 pub fn publication_demand()->RetirementDemand{header(7*size_of::<u64>())}
 /// ⛽️ Quotes the lock and the seven actual publication writes.
 pub fn publication_work_demand()->u64{8}
 /// 📡️ Publishes one complete authority revision under the original Source and Work.
 pub fn publish_into<'r>(&self,generation:u64,revision:[u8;32],effect:&mut RetainedAllocationEffect<'_>,reply:Reply<'r>)->Result<Complete<'r>,ValueError>{self.authenticate(effect)?;let registry=self.registry()?;let demand=Self::publication_demand();if effect.remaining_work_units()?<Self::publication_work_demand()||!retained_clone_grant_admits(effect.grant(),demand){return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}match effect.performed(1){Ok(true)=>{},Ok(false)=>return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"read publication lock exceeded original Work").into()))),Err(error)=>return Ok(reply.complete(Err(error.into())))}let _guard=match registry.state.try_lock(){Ok(guard)=>guard,Err(error)=>return Ok(reply.complete(Err(error.into())))};let sequence=registry.sequence.load(Ordering::Acquire);let Some(terminal)=sequence.checked_add(2)else{return Ok(reply.complete(Err(invalid("read publication sequence overflow").into())))};if sequence&1!=0{return Ok(reply.complete(Err(invalid("read publication sequence is active").into())))}let words=std::array::from_fn::<_,4,_>(|index|u64::from_le_bytes(revision[index*8..index*8+8].try_into().expect("fixed revision word")));match effect.performed(7){Ok(true)=>{},Ok(false)=>return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"read publication exceeded original Work").into()))),Err(error)=>return Ok(reply.complete(Err(error.into())))}if registry.sequence.compare_exchange(sequence,sequence+1,Ordering::AcqRel,Ordering::Acquire).is_err(){return Ok(reply.complete(Err(invalid("read publication sequence changed under its lock").into())))}registry.generation.store(generation,Ordering::Relaxed);for(index,word)in words.into_iter().enumerate(){registry.revision[index].store(word,Ordering::Relaxed)}registry.sequence.store(terminal,Ordering::Release);Ok(reply.complete(Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()}))))}
}
